import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import type { Session } from "@supabase/supabase-js";
import { isSupabaseConfigured, supabase } from "./lib/supabase";
import { starterProducts } from "./starterProducts";

type Employee = { id:string; name:string; email:string; role:"employee"|"admin"; active:boolean };
type Campaign = { id:string; label:string; budget:number; nomination_limit:number; vote_limit:number; start_at:string; nomination_deadline:string; voting_deadline:string; purchase_at:string; status:string };
type Product = { id:string; brand:string; name:string; category:string; size:string; reference_price:number|null; image_path:string|null; origin:"catalog"|"employee"; approval_status:string; active:boolean };
type CampaignMember = { id:string; campaign_id:string; employee_id:string; name_snapshot:string; email_snapshot:string; active:boolean };
type Nomination = { id:string; campaign_id:string; product_id:string; employee_id:string; nominator_name:string; created_at:string };
type Vote = { id:string; campaign_id:string; product_id:string; employee_id:string; voter_name:string; kind:"nomination"|"regular"; created_at:string };
type Comment = { id:string; campaign_id:string; product_id:string; employee_id:string; author_name:string; body:string; created_at:string };
type PurchaseItem = { id:string; campaign_id:string; product_id:string; rank:number; vote_count:number; unit_price:number; suggested_quantity:number; final_quantity:number|null; purchased:boolean; note:string|null };
type Phase = "upcoming"|"nomination"|"voting"|"results"|"purchase";

const icons:Record<string,string>={洋芋片:"◒",餅乾:"▦",巧克力:"◆",糖果果凍:"●",米果:"❋",堅果果乾:"♧",海苔肉乾:"▤",飲料:"◫"};
const tones=["tone-1","tone-2","tone-3","tone-4","tone-5","tone-6"];

function phaseOf(c:Campaign):Phase { const now=Date.now(); if(now<+new Date(c.start_at))return"upcoming";if(now<+new Date(c.nomination_deadline))return"nomination";if(now<+new Date(c.voting_deadline))return"voting";if(now<+new Date(c.purchase_at))return"results";return"purchase" }
function shortDate(value:string){return new Intl.DateTimeFormat("zh-TW",{month:"numeric",day:"numeric"}).format(new Date(value))}
function dateTimeInput(value:string){const d=new Date(value);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
function errorText(error:unknown){return error instanceof Error?error.message:"操作失敗，請稍後再試"}
function productImageUrl(path:string|null){return path?supabase.storage.from("product-images").getPublicUrl(path).data.publicUrl:""}
async function uploadProductImage(file:File,employeeId:string){if(file.size>5*1024*1024)throw new Error("圖片不可超過 5MB");if(!["image/jpeg","image/png","image/webp","image/gif"].includes(file.type))throw new Error("僅支援 JPG、PNG、WebP 或 GIF 圖片");const ext=(file.name.split(".").pop()||"jpg").toLowerCase().replace(/[^a-z0-9]/g,"");const path=`${employeeId}/${crypto.randomUUID()}.${ext||"jpg"}`;const {error}=await supabase.storage.from("product-images").upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return path}

export default function App(){
  const [session,setSession]=useState<Session|null>(null);
  const [employee,setEmployee]=useState<Employee|null>(null);
  const [loading,setLoading]=useState(true);
  const [denied,setDenied]=useState(false);
  const [route,setRoute]=useState(()=>location.hash||"#/");

  useEffect(()=>{
    if(!isSupabaseConfigured){setLoading(false);return}
    supabase.auth.getSession().then(({data})=>setSession(data.session));
    const {data}=supabase.auth.onAuthStateChange((_event,next)=>setSession(next));
    return()=>data.subscription.unsubscribe();
  },[]);

  useEffect(()=>{
    const handleRouteChange=()=>setRoute(location.hash||"#/");
    window.addEventListener("hashchange",handleRouteChange);
    return()=>window.removeEventListener("hashchange",handleRouteChange);
  },[]);

  useEffect(()=>{
    if(!session){setEmployee(null);setDenied(false);setLoading(false);return}
    setLoading(true);
    supabase.from("employees").select("id,name,email,role,active").eq("user_id",session.user.id).maybeSingle()
      .then(({data,error})=>{setEmployee(data as Employee|null);setDenied(!data||Boolean(error));setLoading(false)});
  },[session]);

  if(!isSupabaseConfigured)return <SetupScreen/>;
  if(loading)return <main className="loading-screen">正在確認公司名單…</main>;
  if(!session)return <Login/>;
  if(denied||!employee)return <Unauthorized email={session.user.email??""}/>;
  const adminRoute=route.startsWith("#/admin");
  if(adminRoute&&employee.role!=="admin")return <Unauthorized email={employee.email} adminOnly/>;
  return adminRoute?<AdminApp employee={employee}/>:<EmployeeApp employee={employee}/>;
}

function SetupScreen(){return <main className="system-card"><p className="section-kicker">連線設定</p><h1>網站程式已準備連接 Supabase</h1><p>請建立 <code>.env.local</code>，填入 Project URL 與 Publishable Key，再重新啟動網站。</p><code>VITE_SUPABASE_URL=...<br/>VITE_SUPABASE_PUBLISHABLE_KEY=...</code></main>}

function Login(){
  const [email,setEmail]=useState("");const [busy,setBusy]=useState(false);const [message,setMessage]=useState("");const [error,setError]=useState(false);
  async function submit(e:FormEvent){e.preventDefault();setBusy(true);setMessage("");setError(false);const {error}=await supabase.auth.signInWithOtp({email:email.trim(),options:{emailRedirectTo:location.href.split("#")[0]}});setBusy(false);if(error){setError(true);setMessage(error.message)}else setMessage("登入連結已寄出，請到信箱點擊後回到這個頁面。")}
  return <main className="auth-shell"><section className="auth-brand-panel"><div className="brand"><span className="brand-mark">S</span><div><strong>Snack Vote</strong><small>公司零食共選</small></div></div><div className="auth-copy"><p className="section-kicker">MONTHLY SNACK CLUB</p><h1>把想吃的，<br/>變成下個月的零食。</h1><p>同仁提名、公開具名投票，再依預算產生採購建議。規則透明，選擇也更有參與感。</p></div><div className="auth-flow"><span>01 提名</span><span>02 投票</span><span>03 結果揭曉</span><span>04 安排採購</span></div></section><section className="auth-panel"><form className="auth-card" onSubmit={submit}><p className="section-kicker">EMPLOYEE SIGN IN</p><h2>使用公司 Email 登入</h2><p>不需要設定密碼。系統只允許管理者名單中的 Email 查看與參與。</p><label>Email<input type="email" required autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@company.com"/></label><button className="auth-submit" disabled={busy}>{busy?"寄送中…":"寄送登入連結"}</button>{message&&<p className={`auth-message ${error?"error":""}`}>{message}</p>}<small className="auth-note">若未收到信，請先檢查垃圾郵件，或向管理者確認名單中的 Email 是否正確。</small></form></section></main>
}

function Unauthorized({email,adminOnly=false}:{email:string;adminOnly?:boolean}){return <main className="system-card"><p className="section-kicker">ACCESS CONTROL</p><h1>{adminOnly?"這個頁面僅限管理者":"此 Email 不在啟用名單中"}</h1><p>{email}</p><p>{adminOnly?"你仍可回到員工頁面。":"請聯絡管理者確認名單，完成後重新登入。"}</p><button className="auth-submit" onClick={()=>adminOnly?location.hash="#/":supabase.auth.signOut()}>{adminOnly?"回員工頁面":"登出"}</button></main>}

function EmployeeApp({employee}:{employee:Employee}){
  const [campaign,setCampaign]=useState<Campaign|null>(null);const [products,setProducts]=useState<Product[]>([]);const [nominations,setNominations]=useState<Nomination[]>([]);const [votes,setVotes]=useState<Vote[]>([]);const [comments,setComments]=useState<Comment[]>([]);const [busy,setBusy]=useState(true);const [query,setQuery]=useState("");const [category,setCategory]=useState("全部");const [draftNominations,setDraftNominations]=useState<string[]>([]);const [toast,setToast]=useState("");const [customOpen,setCustomOpen]=useState(false);const [commentDrafts,setCommentDrafts]=useState<Record<string,string>>({});
  const load=useCallback(async(silent=false)=>{if(!silent)setBusy(true);const {data:c}=await supabase.from("campaigns").select("*").eq("status","active").order("start_at",{ascending:true});const all=(c??[]) as Campaign[];const now=Date.now();const current=[...all].reverse().find(x=>+new Date(x.start_at)<=now)??all[0]??null;setCampaign(current);if(!current){setBusy(false);return}const [{data:p},{data:n},{data:v},{data:co}]=await Promise.all([supabase.from("products").select("*").eq("active",true).order("category"),supabase.from("nominations").select("*").eq("campaign_id",current.id),supabase.from("votes").select("*").eq("campaign_id",current.id),supabase.from("comments").select("*").eq("campaign_id",current.id).is("deleted_at",null).order("created_at")]);setProducts((p??[]) as Product[]);setNominations((n??[]) as Nomination[]);setVotes((v??[]) as Vote[]);setComments((co??[]) as Comment[]);setDraftNominations(((n??[]) as Nomination[]).filter(x=>x.employee_id===employee.id).map(x=>x.product_id));setBusy(false)},[employee.id]);
  useEffect(()=>{void load(false)},[load]);
  useEffect(()=>{if(!campaign)return;const channel=supabase.channel(`campaign-${campaign.id}`).on("postgres_changes",{event:"*",schema:"public"},()=>void load(true)).subscribe();return()=>{void supabase.removeChannel(channel)}},[campaign?.id,load]);
  function notify(message:string){setToast(message);setTimeout(()=>setToast(""),2600)}
  if(busy)return <main className="loading-screen">同步本月零食清單…</main>;
  if(!campaign)return <ShellHeader employee={employee}><section className="empty-campaign"><h2>本期活動尚未建立</h2><p>請等待管理者設定本月日期、預算與參與名單。</p></section></ShellHeader>;
  const phase=phaseOf(campaign);const myVotes=votes.filter(v=>v.employee_id===employee.id);const categories=["全部",...new Set(products.map(p=>p.category))];const nominatedProducts=new Set(nominations.map(n=>n.product_id));
  const voteCount=(productId:string)=>votes.filter(v=>v.product_id===productId).length;const rankedProducts=products.filter(p=>nominatedProducts.has(p.id)).sort((a,b)=>voteCount(b.id)-voteCount(a.id)||a.name.localeCompare(b.name,"zh-Hant"));const rankMap=new Map(rankedProducts.map((p,index)=>[p.id,index+1]));const shown=products.filter(p=>(phase==="nomination"||phase==="upcoming"||nominatedProducts.has(p.id))&&(category==="全部"||p.category===category)&&`${p.brand}${p.name}${p.category}`.toLowerCase().includes(query.trim().toLowerCase())).sort((a,b)=>["voting","results","purchase"].includes(phase)?voteCount(b.id)-voteCount(a.id)||a.name.localeCompare(b.name,"zh-Hant"):a.category.localeCompare(b.category,"zh-Hant"));
  async function toggleNomination(product:Product){if(phase!=="nomination")return;const selected=draftNominations.includes(product.id);if(!selected&&draftNominations.length>=campaign!.nomination_limit)return notify(`最多提名 ${campaign!.nomination_limit} 項`);if(!selected){const others=nominations.filter(n=>n.product_id===product.id&&n.employee_id!==employee.id);if(others.length&&!confirm(`這項已由 ${others.map(x=>x.nominator_name).join("、")} 提名。\n仍要共同提名並固定計入 1 票嗎？`))return}const previousDraft=draftNominations;const previousNominations=nominations;const previousVotes=votes;const next=selected?draftNominations.filter(id=>id!==product.id):[...draftNominations,product.id];setDraftNominations(next);if(selected){setNominations(nominations.filter(n=>n.employee_id!==employee.id||n.product_id!==product.id));setVotes(votes.filter(v=>v.employee_id!==employee.id||v.product_id!==product.id||v.kind!=="nomination"))}else{const now=new Date().toISOString();setNominations([...nominations,{id:`optimistic-n-${product.id}`,campaign_id:campaign!.id,product_id:product.id,employee_id:employee.id,nominator_name:employee.name,created_at:now}]);setVotes([...votes,{id:`optimistic-v-${product.id}`,campaign_id:campaign!.id,product_id:product.id,employee_id:employee.id,voter_name:employee.name,kind:"nomination",created_at:now}])}const {error}=await supabase.rpc("set_nominations",{p_campaign_id:campaign!.id,p_product_ids:next});if(error){setDraftNominations(previousDraft);setNominations(previousNominations);setVotes(previousVotes);notify(error.message)}else{notify(selected?"已取消提名，名額與固定票已返還":"已加入提名並計入固定票");await load(true)}}
  async function toggleVote(product:Product){if(phase!=="voting")return;const fixed=myVotes.some(v=>v.product_id===product.id&&v.kind==="nomination");if(fixed)return notify("提名票已鎖定，投票階段不能取消");const regular=myVotes.filter(v=>v.kind==="regular").map(v=>v.product_id);const next=regular.includes(product.id)?regular.filter(id=>id!==product.id):[...regular,product.id];if(next.length+myVotes.filter(v=>v.kind==="nomination").length>campaign!.vote_limit)return notify(`本期最多 ${campaign!.vote_limit} 票`);const previous=votes;const otherVotes=votes.filter(v=>v.employee_id!==employee.id||v.kind!=="regular");const optimistic=next.map(productId=>({id:`optimistic-${productId}`,campaign_id:campaign!.id,product_id:productId,employee_id:employee.id,voter_name:employee.name,kind:"regular" as const,created_at:new Date().toISOString()}));setVotes([...otherVotes,...optimistic]);const {error}=await supabase.rpc("set_regular_votes",{p_campaign_id:campaign!.id,p_product_ids:next});if(error){setVotes(previous);notify(error.message)}else{notify(regular.includes(product.id)?"已取消這一票":"投票已更新");await load(true)}}
  async function addCustomProduct(e:FormEvent<HTMLFormElement>){e.preventDefault();if(draftNominations.length>=campaign!.nomination_limit)return notify(`已達提名上限 ${campaign!.nomination_limit} 項`);const form=new FormData(e.currentTarget);const file=form.get("image") instanceof File&&form.get("image") as File;try{const {data,error}=await supabase.rpc("add_custom_product_and_nominate",{p_campaign_id:campaign!.id,p_name:String(form.get("name")),p_category:String(form.get("category")),p_brand:String(form.get("brand")||""),p_size:String(form.get("size")||""),p_reference_price:form.get("reference_price")?Number(form.get("reference_price")):null,p_source_url:null});if(error)throw error;if(file&&file.size>0){const path=await uploadProductImage(file,employee.id);const attached=await supabase.rpc("set_product_image",{p_product_id:data,p_image_path:path});if(attached.error)throw attached.error}setCustomOpen(false);notify("商品已送審，並先計入你的提名與固定票");await load(true)}catch(error){const text=errorText(error);notify(text.startsWith("DUPLICATE_PRODUCT")?"商品庫已有相同品項，請直接提名既有商品":text)}}
  async function addComment(productId:string){const body=(commentDrafts[productId]??"").trim();if(!body)return;const previous=comments;const optimistic:Comment={id:`optimistic-${crypto.randomUUID()}`,campaign_id:campaign!.id,product_id:productId,employee_id:employee.id,author_name:employee.name,body,created_at:new Date().toISOString()};setComments([...comments,optimistic]);setCommentDrafts(x=>({...x,[productId]:""}));const {error}=await supabase.from("comments").insert({campaign_id:campaign!.id,product_id:productId,employee_id:employee.id,author_name:employee.name,body});if(error){setComments(previous);setCommentDrafts(x=>({...x,[productId]:body}));return notify(error.message)}await load(true)}
  const copy=phase==="nomination"?["商品提名中","把想吃的，放進本月候選單",`截止前可隨時更換；每項提名固定使用 1 票。`]:phase==="voting"?["具名投票中","本月零食，現在由大家決定",`你共有 ${campaign.vote_limit} 票；額外票可在截止前更換。`]:phase==="results"?["結果揭曉中","票數已鎖定，看看本月結果","排名與具名票數已公開。"]:phase==="upcoming"?["本期尚未開始","本月零食活動即將開始",`提名將於 ${shortDate(campaign.start_at)} 開放。`]:["安排採購中","本月採購清單整理中","管理者正依排名、預算與實際售價確認數量。"];
  return <ShellHeader employee={employee}><section className="hero"><div className="hero-main"><div className="eyebrow"><span className="live-dot"/>{copy[0]} · {campaign.label}</div><h1>{copy[1]}</h1><p>{copy[2]}</p><div className="quota-row"><div className="quota-card"><span>我的提名</span><strong>{draftNominations.length}<small>／{campaign.nomination_limit}</small></strong></div><div className="quota-card"><span>本期票數</span><strong>{myVotes.length}<small>／{campaign.vote_limit}</small></strong></div></div></div><Timeline campaign={campaign} phase={phase}/></section><section className="content-head"><div><p className="section-kicker">SNACK CATALOG</p><h2>{phase==="nomination"?"今天想提名哪一款？":"看看大家支持誰"}</h2></div>{phase==="nomination"&&<button className="custom-product-button" onClick={()=>setCustomOpen(x=>!x)}>＋ 找不到商品？自行新增</button>}</section>{customOpen&&<form className="custom-product-form" onSubmit={addCustomProduct}><div><strong>新增商品並提名</strong><small>送出後會先列為待審商品；若被退回，提名名額與固定票會自動返還。</small></div><input required name="name" placeholder="商品名稱"/><input name="brand" placeholder="品牌（選填）"/><select required name="category" defaultValue=""><option value="" disabled>選擇分類</option>{Object.keys(icons).map(x=><option key={x}>{x}</option>)}</select><input name="size" placeholder="規格（選填）"/><input name="reference_price" type="number" min="0" placeholder="參考價（選填）"/><label className="image-input">商品圖<input name="image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"/></label><button>送出並提名</button></form>}<div className="filters"><label className="search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜尋商品、品牌或分類"/></label><div className="category-list">{categories.map(c=><button key={c} className={c===category?"active":""} onClick={()=>setCategory(c)}>{c}</button>)}</div></div><section className="product-grid">{shown.map((p,index)=>{const ns=nominations.filter(n=>n.product_id===p.id);const vs=votes.filter(v=>v.product_id===p.id);const pcs=comments.filter(c=>c.product_id===p.id);const selected=draftNominations.includes(p.id);const voted=myVotes.some(v=>v.product_id===p.id);return <article className="product-card" key={p.id}><div className={`product-visual ${tones[index%tones.length]} ${p.image_path?"has-image":""}`}>{p.image_path?<img src={productImageUrl(p.image_path)} alt={`${p.brand} ${p.name}`}/>:<span>{icons[p.category]??"✦"}</span>}<small>{p.category}</small>{rankMap.has(p.id)&&["voting","results","purchase"].includes(phase)&&<b>第 {rankMap.get(p.id)} 名</b>}</div><div className="product-body"><div className="brand-line"><span>{p.brand}{p.approval_status==="pending"?" · 待管理者審核":""}</span><strong>{p.reference_price==null?"待確認":`參考 $${p.reference_price}`}</strong></div><h3>{p.name}</h3><p>{p.size}</p>{ns.length>0&&<div className="nominator"><span>{ns.map(n=>n.nominator_name).join("、")} 提名</span></div>}{["voting","results","purchase"].includes(phase)&&<div className="voter-line"><strong>第 {rankMap.get(p.id)} 名 · {vs.length} 票</strong><span>{vs.map(v=>v.voter_name).join("、")||"尚無投票"}</span></div>}<div className="card-actions">{phase==="nomination"?<button className={`primary-action ${selected?"selected":""}`} onClick={()=>toggleNomination(p)}>{selected?"✓ 已提名（可取消）":"＋ 納入本期"}</button>:phase==="voting"?<button className={`primary-action ${voted?"selected":""}`} onClick={()=>toggleVote(p)}>{voted?(myVotes.some(v=>v.product_id===p.id&&v.kind==="nomination")?"▣ 提名票":"✓ 已投票"):"投一票"}</button>:<span className="rank-label">第 {rankMap.get(p.id)} 名 · {vs.length} 票</span>}</div>{["nomination","voting"].includes(phase)&&<div className="comment-box"><div className="comment-list">{pcs.slice(-3).map(c=><p key={c.id}><strong>{c.author_name}</strong>{c.body}</p>)}{!pcs.length&&<small>還沒有人留言，來幫這款拉票吧。</small>}</div><div className="comment-compose"><input maxLength={500} value={commentDrafts[p.id]??""} onChange={e=>setCommentDrafts(x=>({...x,[p.id]:e.target.value}))} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();void addComment(p.id)}}} placeholder="留言拉票…"/><button onClick={()=>addComment(p.id)}>送出</button></div></div>}</div></article>})}{!shown.length&&<div className="empty-campaign">目前沒有符合條件的商品。</div>}</section>{toast&&<div className="toast">{toast}</div>}</ShellHeader>
}

function ShellHeader({employee,children}:{employee:Employee;children:React.ReactNode}){return <main className="employee-shell"><header className="topbar"><div className="brand"><span className="brand-mark">S</span><div><strong>Snack Vote</strong><small>公司零食共選</small></div></div><div className="top-actions">{employee.role==="admin"&&<a href="#/admin">管理後台</a>}<button onClick={()=>supabase.auth.signOut()}>登出</button><div className="profile"><span className="avatar">{employee.name.slice(0,1)}</span><div><strong>{employee.name}</strong><small>{employee.email}</small></div></div></div></header>{children}<footer>商品與價格僅供採購參考，實際售價及庫存以門市為準。</footer></main>}

function Timeline({campaign,phase}:{campaign:Campaign;phase:Phase}){const index={upcoming:-1,nomination:0,voting:1,results:2,purchase:3}[phase];const items=[["開始",campaign.start_at],["提名截止",campaign.nomination_deadline],["投票截止",campaign.voting_deadline],["安排採購",campaign.purchase_at]];return <div className="timeline-panel"><div className="milestone-row">{items.map((x,i)=><div key={x[0]} className={`milestone ${i<=index?"done":""} ${i===index?"current":""}`}><span>{i+1}</span><strong>{x[0]}</strong><small>{shortDate(x[1])}</small></div>)}</div><div className="period-row"><div className={`period ${phase==="nomination"?"active":""}`}><strong>提名階段</strong><small>{shortDate(campaign.start_at)}–{shortDate(campaign.nomination_deadline)}</small></div><div className={`period ${phase==="voting"?"active":""}`}><strong>投票階段</strong><small>{shortDate(campaign.nomination_deadline)}–{shortDate(campaign.voting_deadline)}</small></div><div className={`period ${phase==="results"?"active":""}`}><strong>結果揭曉階段</strong><small>{shortDate(campaign.voting_deadline)}–{shortDate(campaign.purchase_at)}</small></div></div></div>}

type AdminTab="overview"|"campaign"|"employees"|"products"|"pending"|"purchase"|"history";
const adminTabs:{id:AdminTab;icon:string;label:string}[]=[{id:"overview",icon:"⌂",label:"管理總覽"},{id:"campaign",icon:"◫",label:"本期活動"},{id:"employees",icon:"◎",label:"員工名單"},{id:"products",icon:"▦",label:"商品資料庫"},{id:"pending",icon:"◇",label:"待審商品"},{id:"purchase",icon:"✓",label:"採購清單"},{id:"history",icon:"↺",label:"歷史紀錄"}];

function AdminApp({employee}:{employee:Employee}){
  const [tab,setTab]=useState<AdminTab>("overview");const [employees,setEmployees]=useState<Employee[]>([]);const [campaigns,setCampaigns]=useState<Campaign[]>([]);const [members,setMembers]=useState<CampaignMember[]>([]);const [products,setProducts]=useState<Product[]>([]);const [nominations,setNominations]=useState<Nomination[]>([]);const [votes,setVotes]=useState<Vote[]>([]);const [comments,setComments]=useState<Comment[]>([]);const [purchases,setPurchases]=useState<PurchaseItem[]>([]);const [name,setName]=useState("");const [email,setEmail]=useState("");const [message,setMessage]=useState("");const [busy,setBusy]=useState(false);const [newCampaign,setNewCampaign]=useState(false);const [editingProduct,setEditingProduct]=useState<Product|null>(null);
  const latest=campaigns[0]??null;const pending=products.filter(p=>p.approval_status==="pending");
  const load=useCallback(async()=>{const [{data:e},{data:c},{data:m},{data:p},{data:n},{data:v},{data:co},{data:pi}]=await Promise.all([supabase.from("employees").select("id,name,email,role,active").order("name"),supabase.from("campaigns").select("*").order("start_at",{ascending:false}),supabase.from("campaign_members").select("*").order("name_snapshot"),supabase.from("products").select("*").order("category"),supabase.from("nominations").select("*").order("created_at"),supabase.from("votes").select("*").order("created_at"),supabase.from("comments").select("*").is("deleted_at",null).order("created_at"),supabase.from("purchase_items").select("*").order("rank")]);setEmployees((e??[]) as Employee[]);setCampaigns((c??[]) as Campaign[]);setMembers((m??[]) as CampaignMember[]);setProducts((p??[]) as Product[]);setNominations((n??[]) as Nomination[]);setVotes((v??[]) as Vote[]);setComments((co??[]) as Comment[]);setPurchases((pi??[]) as PurchaseItem[])},[]);useEffect(()=>{void load()},[load]);
  function flash(text:string){setMessage(text);window.setTimeout(()=>setMessage(""),3500)}
  async function addEmployee(e:FormEvent){e.preventDefault();setBusy(true);const {error}=await supabase.from("employees").insert({name:name.trim(),email:email.trim().toLowerCase(),role:"employee"});setBusy(false);if(error)return flash(error.message);setName("");setEmail("");flash("員工已新增，可使用該 Email 登入");await load()}
  async function updateEmployee(row:Employee,patch:Partial<Employee>){if(row.id===employee.id&&patch.active===false)return flash("不能停用目前登入的管理者");const {error}=await supabase.from("employees").update(patch).eq("id",row.id);if(error)flash(error.message);else await load()}
  async function saveCampaign(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const form=new FormData(e.currentTarget);const wasNew=!form.get("id");const payload={label:String(form.get("label")),budget:Number(form.get("budget")),nomination_limit:Number(form.get("nomination_limit")),vote_limit:Number(form.get("vote_limit")),start_at:new Date(String(form.get("start_at"))).toISOString(),nomination_deadline:new Date(String(form.get("nomination_deadline"))).toISOString(),voting_deadline:new Date(String(form.get("voting_deadline"))).toISOString(),purchase_at:new Date(String(form.get("purchase_at"))).toISOString(),status:String(form.get("status")),created_by:employee.id};let id=String(form.get("id")||"");const result=id?await supabase.from("campaigns").update(payload).eq("id",id).select("id").single():await supabase.from("campaigns").insert(payload).select("id").single();if(result.error){setBusy(false);return flash(result.error.message)}id=result.data.id;if(wasNew){const snap=await supabase.rpc("snapshot_active_employees",{p_campaign_id:id});if(snap.error){setBusy(false);return flash(snap.error.message)}}setBusy(false);setNewCampaign(false);flash(wasNew?"本期活動已建立，啟用員工已全數納入":"活動設定已更新，本期參與名單維持不變");await load()}
  async function addProduct(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const form=new FormData(e.currentTarget);try{const image=form.get("image");const imagePath=image instanceof File&&image.size>0?await uploadProductImage(image,employee.id):null;const payload={brand:String(form.get("brand")).trim(),name:String(form.get("name")).trim(),category:String(form.get("category")).trim(),size:String(form.get("size")).trim(),reference_price:form.get("reference_price")?Number(form.get("reference_price")):null,image_path:imagePath,origin:"catalog",approval_status:"approved",active:true};const {error}=await supabase.from("products").insert(payload);if(error)throw error;e.currentTarget.reset();flash("商品已加入資料庫");await load()}catch(error){flash(errorText(error))}finally{setBusy(false)}}
  async function addStarterProducts(){const existing=new Set(products.filter(p=>p.active).map(p=>`${p.brand.trim().toLowerCase()}|${p.name.trim().toLowerCase()}|${p.size.trim().toLowerCase()}`));const rows=starterProducts.filter(([brand,name,,size])=>!existing.has(`${brand.toLowerCase()}|${name.toLowerCase()}|${size.toLowerCase()}`)).map(([brand,name,category,size])=>({brand,name,category,size,reference_price:null,source_url:null,origin:"catalog",approval_status:"approved",active:true}));if(!rows.length)return flash("基礎商品都已經在資料庫中");if(!confirm(`將加入 ${rows.length} 項基礎商品，價格先標示為待確認。確定繼續嗎？`))return;setBusy(true);const {error}=await supabase.from("products").insert(rows);setBusy(false);if(error)return flash(error.message);flash(`已加入 ${rows.length} 項基礎商品`);await load()}
  async function updateProduct(id:string,patch:Record<string,unknown>,success:string){const {error}=await supabase.from("products").update(patch).eq("id",id);if(error)flash(error.message);else{flash(success);await load()}}
  async function replaceProductImage(product:Product,file:File){try{setBusy(true);const path=await uploadProductImage(file,employee.id);const {error}=await supabase.rpc("set_product_image",{p_product_id:product.id,p_image_path:path});if(error)throw error;flash("商品圖片已更新");await load()}catch(error){flash(errorText(error))}finally{setBusy(false)}}
  async function reviewProduct(product:Product,decision:"approved"|"rejected"){if(decision==="rejected"&&!confirm(`退回「${product.name}」後，相關提名與固定票會立即移除並返還名額。確定退回嗎？`))return;const {data,error}=await supabase.rpc("review_product",{p_product_id:product.id,p_decision:decision});if(error)return flash(error.message);flash(decision==="approved"?"商品已核准並加入商品庫":`商品已退回，已返還 ${data??0} 筆提名與固定票`);await load()}
  function editProduct(product:Product){setEditingProduct(product)}
  async function saveEditedProduct(form:FormData,image:File|null){if(!editingProduct)return;try{setBusy(true);let imagePath=editingProduct.image_path;if(image){imagePath=await uploadProductImage(image,employee.id)}const payload={brand:String(form.get("brand")||"").trim(),name:String(form.get("name")||"").trim(),category:String(form.get("category")||"").trim(),size:String(form.get("size")||"").trim(),reference_price:form.get("reference_price")?Number(form.get("reference_price")):null,image_path:imagePath,active:String(form.get("active"))==="true"};const {error}=await supabase.from("products").update(payload).eq("id",editingProduct.id);if(error)throw error;setEditingProduct(null);flash("商品資料已完整更新");await load()}catch(error){flash(errorText(error))}finally{setBusy(false)}}
  async function generatePurchase(){if(!latest)return flash("請先建立活動");setBusy(true);const {data,error}=await supabase.rpc("generate_purchase_plan",{p_campaign_id:latest.id});setBusy(false);if(error)return flash(error.message);const result=data as {remaining:number;missing_prices:number};flash(result.missing_prices?`清單已產生；${result.missing_prices} 項尚未設定價格，因此未配置數量`:`清單已產生，預算餘額 NT$ ${Number(result.remaining).toLocaleString()}`);await load()}
  async function updatePurchase(row:PurchaseItem,patch:Partial<PurchaseItem>){const {error}=await supabase.from("purchase_items").update(patch).eq("id",row.id);if(error)flash(error.message);else await load()}
  async function toggleCampaignMember(row:Employee){if(!latest)return;const current=members.find(m=>m.campaign_id===latest.id&&m.employee_id===row.id);const active=!(current?.active??false);const result=current?await supabase.from("campaign_members").update({active}).eq("id",current.id):await supabase.from("campaign_members").insert({campaign_id:latest.id,employee_id:row.id,name_snapshot:row.name,email_snapshot:row.email,active});if(result.error)flash(result.error.message);else{flash(active?`${row.name} 已加入本期`:`${row.name} 已從本期排除`);await load()}}
  const title=adminTabs.find(x=>x.id===tab)?.label??"管理總覽";
  return <main className="admin-shell"><aside className="admin-nav"><div className="brand admin-brand"><span className="brand-mark">S</span><div><strong>Snack Vote</strong><small>管理後台</small></div></div><nav>{adminTabs.map(item=><button key={item.id} className={tab===item.id?"active":""} onClick={()=>setTab(item.id)}><span>{item.icon}</span>{item.label}{item.id==="pending"&&pending.length>0&&<b className="nav-badge">{pending.length}</b>}</button>)}<a href="#/"><button><span>←</span>回員工頁面</button></a></nav><div className="admin-user"><span className="avatar">{employee.name.slice(0,1)}</span><div><strong>{employee.name}</strong><small>系統管理者</small></div></div></aside><section className="admin-main"><header className="admin-top"><div><p className="section-kicker">ADMIN CONSOLE</p><h1>{title}</h1></div><div className="admin-status">{latest&&<span className={`status-pill ${phaseOf(latest)}`}>{latest.label} · {phaseLabel(phaseOf(latest))}</span>}<button className="table-action" onClick={()=>supabase.auth.signOut()}>登出</button></div></header>{message&&<div className="admin-toast">{message}</div>}<div className="admin-content">
    {tab==="overview"&&<><div className="stat-grid"><article><span>啟用員工</span><strong>{employees.filter(e=>e.active).length}</strong><small>人</small></article><article><span>活動紀錄</span><strong>{campaigns.length}</strong><small>期</small></article><article><span>啟用商品</span><strong>{products.filter(p=>p.active&&p.approval_status==="approved").length}</strong><small>項</small></article><article><span>待審商品</span><strong>{pending.length}</strong><small>項</small></article></div><div className="admin-two"><section className="admin-card"><div className="card-title"><div><p className="section-kicker">CURRENT CAMPAIGN</p><h2>{latest?.label??"尚未建立本期活動"}</h2></div>{latest&&<button onClick={()=>setTab("campaign")}>編輯設定 →</button>}</div>{latest?<><Timeline campaign={latest} phase={phaseOf(latest)}/><div className="rule-note"><strong>本期規則</strong><span>預算 NT$ {Number(latest.budget).toLocaleString()} · 每人提名 {latest.nomination_limit} 項 · 共 {latest.vote_limit} 票</span></div></>:<div className="admin-empty"><button className="solid-button" onClick={()=>setTab("campaign")}>建立第一期活動</button></div>}</section><section className="admin-card"><div className="card-title"><div><p className="section-kicker">QUICK ACTIONS</p><h2>接下來要處理</h2></div></div><div className="quick-list"><button onClick={()=>setTab("pending")}><strong>{pending.length}</strong><span>筆待審商品</span><em>前往審核 →</em></button><button onClick={()=>setTab("purchase")}><strong>{latest?votes.filter(v=>v.campaign_id===latest.id).length:0}</strong><span>張本期票數</span><em>安排採購 →</em></button><button onClick={()=>setTab("employees")}><strong>{employees.filter(e=>e.active).length}</strong><span>位啟用員工</span><em>管理名單 →</em></button></div></section></div></>}
    {tab==="campaign"&&<><div className="section-actions"><p>{newCampaign?"設定新一期活動；既有活動會保留在歷史紀錄。":"目前顯示最近一期，可修改日期、預算與名額。"}</p><button className="solid-button" onClick={()=>setNewCampaign(x=>!x)}>{newCampaign?"取消建立新活動":"＋ 建立下一期"}</button></div><CampaignForm campaign={newCampaign?null:latest} busy={busy} onSubmit={saveCampaign}/>{!newCampaign&&latest&&<CampaignMemberPanel campaign={latest} employees={employees} members={members} onToggle={toggleCampaignMember}/>}</>} 
    {tab==="employees"&&<section className="admin-card"><div className="card-title"><div><p className="section-kicker">EMPLOYEE ROSTER</p><h2>員工名單</h2></div><span className="count-tag">{employees.length} 人</span></div><form className="add-employee" onSubmit={addEmployee}><input required placeholder="姓名" value={name} onChange={e=>setName(e.target.value)}/><input required type="email" placeholder="公司 Email" value={email} onChange={e=>setEmail(e.target.value)}/><button disabled={busy}>＋ 新增員工</button></form><div className="table-wrap"><table><thead><tr><th>姓名</th><th>Email</th><th>權限</th><th>狀態</th><th>操作</th></tr></thead><tbody>{employees.map(row=><tr key={row.id}><td><strong>{row.name}</strong></td><td>{row.email}</td><td><select value={row.role} onChange={e=>updateEmployee(row,{role:e.target.value as Employee["role"]})}><option value="employee">員工</option><option value="admin">管理者</option></select></td><td><span className={row.active?"active-dot":"inactive-dot"}>{row.active?"啟用":"停用"}</span></td><td><button className="table-action" onClick={()=>updateEmployee(row,{active:!row.active})}>{row.active?"停用":"重新啟用"}</button></td></tr>)}</tbody></table></div></section>}
    {tab==="products"&&<><section className="admin-card"><div className="card-title"><div><p className="section-kicker">ADD PRODUCT</p><h2>新增商品</h2></div><button className="seed-button" disabled={busy} onClick={addStarterProducts}>一鍵加入 39 項基礎商品</button></div><form className="product-form product-form-with-image" onSubmit={addProduct}><input name="brand" placeholder="品牌（可空白）"/><input required name="name" placeholder="商品名稱"/><select required name="category" defaultValue=""><option value="" disabled>選擇分類</option>{Object.keys(icons).map(x=><option key={x}>{x}</option>)}</select><input name="size" placeholder="規格，例如 100g"/><input name="reference_price" type="number" min="0" step="1" placeholder="參考價格"/><label className="compact-file">選擇商品圖<input name="image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"/></label><button disabled={busy}>＋ 加入商品庫</button></form><div className="seed-note">圖片支援 JPG、PNG、WebP、GIF，單張上限 5MB。價格、包裝與庫存仍以實際門市為準。</div></section><section className="admin-card"><div className="card-title"><div><p className="section-kicker">PRODUCT CATALOG</p><h2>商品資料庫</h2></div><span className="count-tag">{products.length} 項</span></div><div className="table-wrap"><table><thead><tr><th>圖片</th><th>商品</th><th>分類</th><th>參考價</th><th>來源</th><th>狀態</th><th>操作</th></tr></thead><tbody>{products.filter(p=>p.approval_status!=="pending").map(p=><tr key={p.id}><td>{p.image_path?<img className="product-thumb" src={productImageUrl(p.image_path)} alt=""/>:<span className="thumb-placeholder">{icons[p.category]??"✦"}</span>}</td><td><strong>{p.brand} {p.name}</strong><small className="cell-sub">{p.size||"未填規格"}</small></td><td>{p.category}</td><td>{p.reference_price==null?"待確認":`NT$ ${p.reference_price}`}</td><td>{p.origin==="employee"?"同仁新增":"商品庫"}</td><td><span className={p.active?"active-dot":"inactive-dot"}>{p.active?"啟用":"停用"}</span></td><td><button className="table-action" onClick={()=>editProduct(p)}>修改</button><label className="table-upload">換圖<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onChange={e=>{const file=e.target.files?.[0];if(file)void replaceProductImage(p,file)}}/></label><button className="table-action" onClick={()=>updateProduct(p.id,{active:!p.active},p.active?"商品已停用":"商品已重新啟用")}>{p.active?"停用":"啟用"}</button></td></tr>)}</tbody></table></div></section></>}
    {tab==="pending"&&<section className="admin-card"><div className="card-title"><div><p className="section-kicker">PRODUCT REVIEW</p><h2>同仁新增商品審核</h2></div><span className="count-tag">{pending.length} 項</span></div>{pending.length?<div className="review-grid">{pending.map(p=><article key={p.id}>{p.image_path?<img className="review-image" src={productImageUrl(p.image_path)} alt={p.name}/>:<div className="review-icon">{icons[p.category]??"✦"}</div>}<div><span>{p.category} · {p.brand||"未填品牌"}</span><h3>{p.name}</h3><p>{p.size||"未填規格"} · {p.reference_price==null?"價格待確認":`參考 NT$ ${p.reference_price}`}</p></div><div className="review-actions"><button className="approve" onClick={()=>reviewProduct(p,"approved")}>核准</button><button onClick={()=>reviewProduct(p,"rejected")}>退回並返還票數</button></div></article>)}</div>:<div className="admin-empty">目前沒有待審商品。</div>}</section>}
    {tab==="purchase"&&<PurchasePanel campaign={latest} products={products} purchases={purchases} onGenerate={generatePurchase} onUpdate={updatePurchase}/>} 
    {tab==="history"&&<HistoryPanel campaigns={campaigns} products={products} nominations={nominations} votes={votes} comments={comments} purchases={purchases}/>} 
  </div></section>{editingProduct&&<ProductEditor product={editingProduct} busy={busy} onClose={()=>setEditingProduct(null)} onSave={saveEditedProduct}/>}</main>
}

function phaseLabel(phase:Phase){return({upcoming:"尚未開始",nomination:"提名階段",voting:"投票階段",results:"結果揭曉",purchase:"安排採購"})[phase]}
function CampaignForm({campaign,busy,onSubmit}:{campaign:Campaign|null;busy:boolean;onSubmit:(e:FormEvent<HTMLFormElement>)=>void}){const base=new Date();const defaults={start:new Date(base.getTime()+86400000),nomination:new Date(base.getTime()+8*86400000),voting:new Date(base.getTime()+15*86400000),purchase:new Date(base.getTime()+18*86400000)};return <section className="admin-card form-card"><div className="card-title"><div><p className="section-kicker">CAMPAIGN SETTINGS</p><h2>{campaign?"編輯本期活動":"建立本期活動"}</h2></div>{campaign&&<span className={`status-pill ${phaseOf(campaign)}`}>{phaseLabel(phaseOf(campaign))}</span>}</div><form onSubmit={onSubmit}><input type="hidden" name="id" value={campaign?.id??""}/><div className="form-grid"><label><span>活動名稱</span><input required name="label" defaultValue={campaign?.label??`${base.getFullYear()} 年 ${base.getMonth()+2} 月零食共選`} /></label><label><span>每期預算金額</span><div className="input-prefix"><i>NT$</i><input required name="budget" type="number" min="0" step="1" defaultValue={campaign?.budget??5000}/></div></label><label><span>開始</span><input required name="start_at" type="datetime-local" defaultValue={campaign?dateTimeInput(campaign.start_at):dateTimeInput(defaults.start.toISOString())}/></label><label><span>提名截止</span><input required name="nomination_deadline" type="datetime-local" defaultValue={campaign?dateTimeInput(campaign.nomination_deadline):dateTimeInput(defaults.nomination.toISOString())}/></label><label><span>投票截止</span><input required name="voting_deadline" type="datetime-local" defaultValue={campaign?dateTimeInput(campaign.voting_deadline):dateTimeInput(defaults.voting.toISOString())}/></label><label><span>安排採購</span><input required name="purchase_at" type="datetime-local" defaultValue={campaign?dateTimeInput(campaign.purchase_at):dateTimeInput(defaults.purchase.toISOString())}/></label><label><span>每人提名上限</span><input required name="nomination_limit" type="number" min="1" defaultValue={campaign?.nomination_limit??2}/><small>提名項目會各固定占用一票</small></label><label><span>每人總票數上限</span><input required name="vote_limit" type="number" min="1" defaultValue={campaign?.vote_limit??4}/><small>不得少於提名上限</small></label><label><span>發布狀態</span><select name="status" defaultValue={campaign?.status??"active"}><option value="draft">草稿（員工不可見）</option><option value="active">啟用</option><option value="archived">封存</option></select></label></div><div className="form-footer"><div className="rule-note"><strong>參與名單</strong><span>建立新活動時會納入所有啟用員工；建立後可在下方逐一調整，不會因修改日期而被重設。</span></div><button className="solid-button" disabled={busy}>{busy?"儲存中…":"儲存活動設定"}</button></div></form></section>}

function CampaignMemberPanel({campaign,employees,members,onToggle}:{campaign:Campaign;employees:Employee[];members:CampaignMember[];onToggle:(employee:Employee)=>void}){const rows=members.filter(m=>m.campaign_id===campaign.id);const activeCount=rows.filter(m=>m.active).length;return <section className="admin-card"><div className="card-title"><div><p className="section-kicker">CAMPAIGN MEMBERS</p><h2>本期參與名單</h2></div><span className="count-tag">{activeCount} 人參與</span></div><p className="panel-help">此設定只影響「{campaign.label}」，不會停用員工帳號，也不會改動其他期別。</p><div className="member-grid">{employees.map(row=>{const member=rows.find(m=>m.employee_id===row.id);const checked=member?.active??false;return <label key={row.id} className={checked?"selected":""}><input type="checkbox" checked={checked} onChange={()=>onToggle(row)}/><span className="avatar small">{row.name.slice(0,1)}</span><span><strong>{row.name}</strong><small>{row.email}</small></span><em>{checked?"本期參與":"本期排除"}</em></label>})}</div></section>}

function ProductEditor({product,busy,onClose,onSave}:{product:Product;busy:boolean;onClose:()=>void;onSave:(form:FormData,image:File|null)=>void}){
  const [dirty,setDirty]=useState(false);const [image,setImage]=useState<File|null>(null);const [preview,setPreview]=useState(productImageUrl(product.image_path));const [removeImage,setRemoveImage]=useState(false);
  function requestClose(){if(!dirty||confirm("尚未儲存的修改會遺失，確定關閉嗎？"))onClose()}
  useEffect(()=>{const handle=(event:KeyboardEvent)=>{if(event.key==="Escape")requestClose()};window.addEventListener("keydown",handle);return()=>window.removeEventListener("keydown",handle)},[dirty]);
  useEffect(()=>()=>{if(preview.startsWith("blob:"))URL.revokeObjectURL(preview)},[preview]);
  function selectImage(file:File|null){if(!file)return;if(file.size>5*1024*1024){alert("圖片不可超過 5MB");return}if(!["image/jpeg","image/png","image/webp","image/gif"].includes(file.type)){alert("僅支援 JPG、PNG、WebP 或 GIF 圖片");return}if(preview.startsWith("blob:"))URL.revokeObjectURL(preview);setImage(file);setPreview(URL.createObjectURL(file));setRemoveImage(false);setDirty(true)}
  function remove(){if(preview.startsWith("blob:"))URL.revokeObjectURL(preview);setImage(null);setPreview("");setRemoveImage(true);setDirty(true)}
  function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);form.set("remove_image",String(removeImage));onSave(form,image)}
  return <div className="editor-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)requestClose()}}><section className="product-editor" role="dialog" aria-modal="true" aria-labelledby="product-editor-title"><header><div><p className="section-kicker">PRODUCT EDITOR</p><h2 id="product-editor-title">編輯商品資料</h2><span>{product.origin==="employee"?"同仁新增":"管理者商品庫"} · {product.approval_status==="approved"?"已核准":product.approval_status==="pending"?"待審核":"已退回"}</span></div><button type="button" onClick={requestClose} aria-label="關閉編輯視窗">×</button></header><form onSubmit={submit} onChange={()=>setDirty(true)}><div className="editor-layout"><div className="editor-image"><div className="editor-preview">{preview?<img src={preview} alt="商品圖片預覽"/>:<span>{icons[product.category]??"✦"}<small>尚無商品圖</small></span>}</div><label className="image-change">上傳或更換圖片<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onChange={e=>selectImage(e.target.files?.[0]??null)}/></label>{preview&&<button type="button" className="remove-image" onClick={remove}>移除圖片</button>}<small>JPG、PNG、WebP、GIF，最大 5MB</small></div><div className="editor-fields"><label className="field-wide"><span>商品名稱 *</span><input required name="name" defaultValue={product.name} maxLength={160}/></label><label><span>品牌</span><input name="brand" defaultValue={product.brand} maxLength={80}/></label><label><span>分類 *</span><select required name="category" defaultValue={product.category}>{Object.keys(icons).map(x=><option key={x}>{x}</option>)}</select></label><label><span>規格</span><input name="size" defaultValue={product.size} maxLength={80} placeholder="例如 100g、12入"/></label><label><span>參考價格</span><div className="editor-price"><i>NT$</i><input name="reference_price" type="number" min="0" step="1" defaultValue={product.reference_price??""} placeholder="留空表示待確認"/></div></label><label className="field-wide"><span>商品狀態</span><select name="active" defaultValue={String(product.active)}><option value="true">啟用－員工可在商品庫看到</option><option value="false">停用－保留歷史但不供新提名</option></select></label></div></div><footer><div>{dirty?<><span className="unsaved-dot"/>尚有未儲存的修改</>:"目前沒有修改"}</div><button type="button" className="editor-cancel" onClick={requestClose}>取消</button><button className="editor-save" disabled={busy||!dirty}>{busy?"儲存中…":"儲存商品"}</button></footer></form></section></div>
}

function PurchasePanel({campaign,products,purchases,onGenerate,onUpdate}:{campaign:Campaign|null;products:Product[];purchases:PurchaseItem[];onGenerate:()=>void;onUpdate:(row:PurchaseItem,patch:Partial<PurchaseItem>)=>void}){if(!campaign)return <section className="admin-card"><div className="admin-empty">請先建立本期活動。</div></section>;const rows=purchases.filter(p=>p.campaign_id===campaign.id);const total=rows.reduce((sum,row)=>sum+Number(row.unit_price)*Number(row.final_quantity??row.suggested_quantity),0);const remaining=Number(campaign.budget)-total;return <><div className="purchase-summary"><div><span>本期預算</span><strong>NT$ {Number(campaign.budget).toLocaleString()}</strong></div><div><span>目前清單金額</span><strong>NT$ {total.toLocaleString()}</strong></div><div className={remaining<0?"over-budget":""}><span>{remaining<0?"超出預算":"預算餘額"}</span><strong>NT$ {Math.abs(remaining).toLocaleString()}</strong></div></div><section className="admin-card"><div className="card-title"><div><p className="section-kicker">PURCHASE PLAN</p><h2>{campaign.label} 採購清單</h2></div><button className="solid-button" onClick={onGenerate}>{rows.length?"重新計算建議":"產生採購建議"}</button></div><div className="rule-note purchase-rule"><strong>分配規則</strong><span>只取前 5 名，先依排名每項最多 2 份；剩餘預算再由第 1 名到第 5 名逐輪加購，直到餘額買不起任何品項。未設定價格的商品會暫停分配。</span></div>{rows.length?<div className="table-wrap"><table><thead><tr><th>排名</th><th>商品</th><th>票數</th><th>採購單價</th><th>採購數量</th><th>小計</th><th>完成</th></tr></thead><tbody>{rows.map(row=>{const product=products.find(p=>p.id===row.product_id);const qty=row.final_quantity??row.suggested_quantity;return <tr key={row.id}><td><strong>#{row.rank}</strong></td><td>{product?`${product.brand} ${product.name}`:"商品資料已移除"}{row.unit_price<=0&&<small className="cell-warning">尚未設定價格</small>}</td><td>{row.vote_count} 票</td><td><input className="price-input" type="number" min="0" value={row.unit_price} onChange={e=>onUpdate(row,{unit_price:Number(e.target.value)})}/></td><td><input className="qty-input" type="number" min="0" value={qty} onChange={e=>onUpdate(row,{final_quantity:Number(e.target.value)})}/></td><td>NT$ {(Number(row.unit_price)*qty).toLocaleString()}</td><td><label className="check-label"><input type="checkbox" checked={row.purchased} onChange={e=>onUpdate(row,{purchased:e.target.checked})}/>{row.purchased?"已買":"未買"}</label></td></tr>})}</tbody></table></div>:<div className="admin-empty">投票結束後，按「產生採購建議」。請先在商品資料庫確認前五名商品的參考價格。</div>}</section></>}

function HistoryPanel({campaigns,products,nominations,votes,comments,purchases}:{campaigns:Campaign[];products:Product[];nominations:Nomination[];votes:Vote[];comments:Comment[];purchases:PurchaseItem[]}){const [expanded,setExpanded]=useState<string|null>(null);return <section className="admin-card"><div className="card-title"><div><p className="section-kicker">CAMPAIGN HISTORY</p><h2>所有活動完整紀錄</h2></div><span className="count-tag">{campaigns.length} 期</span></div>{campaigns.length?<div className="history-detail-list">{campaigns.map(c=>{const cv=votes.filter(v=>v.campaign_id===c.id);const cn=nominations.filter(n=>n.campaign_id===c.id);const cc=comments.filter(x=>x.campaign_id===c.id);const cp=purchases.filter(x=>x.campaign_id===c.id);const productIds=[...new Set([...cn.map(n=>n.product_id),...cv.map(v=>v.product_id),...cp.map(p=>p.product_id)])];const ranking=productIds.map(id=>({id,count:cv.filter(v=>v.product_id===id).length})).sort((a,b)=>b.count-a.count||a.id.localeCompare(b.id));const spent=cp.reduce((sum,x)=>sum+Number(x.unit_price)*Number(x.final_quantity??x.suggested_quantity),0);const open=expanded===c.id;return <article className={`history-detail ${open?"open":""}`} key={c.id}><button className="history-summary" onClick={()=>setExpanded(open?null:c.id)}><span><em>{c.status==="archived"?"已封存":phaseLabel(phaseOf(c))}</em><strong>{c.label}</strong><small>{shortDate(c.start_at)}－{shortDate(c.purchase_at)}</small></span><span><b>預算 NT$ {Number(c.budget).toLocaleString()}</b><small>{cv.length} 票 · {cn.length} 筆提名 · {cc.length} 則留言</small></span><i>{open?"收合":"查看完整紀錄"}</i></button>{open&&<div className="history-body"><div className="history-metrics"><span>預算<strong>NT$ {Number(c.budget).toLocaleString()}</strong></span><span>採購清單金額<strong>NT$ {spent.toLocaleString()}</strong></span><span>已完成採購<strong>{cp.filter(x=>x.purchased).length} 項</strong></span></div><div className="table-wrap"><table><thead><tr><th>排名</th><th>商品</th><th>提名者</th><th>票數與投票者</th><th>留言</th><th>採購結果</th></tr></thead><tbody>{ranking.map((r,index)=>{const product=products.find(p=>p.id===r.id);const ns=cn.filter(n=>n.product_id===r.id);const vs=cv.filter(v=>v.product_id===r.id);const cs=cc.filter(x=>x.product_id===r.id);const buy=cp.find(x=>x.product_id===r.id);return <tr key={r.id}><td><strong>#{index+1}</strong></td><td>{product?`${product.brand} ${product.name}`:"商品資料已停用"}</td><td>{ns.map(n=>n.nominator_name).join("、")||"—"}</td><td><strong>{vs.length} 票</strong><small className="cell-sub">{vs.map(v=>v.voter_name).join("、")||"—"}</small></td><td>{cs.length?<details><summary>{cs.length} 則</summary>{cs.map(x=><p className="history-comment" key={x.id}><b>{x.author_name}</b>{x.body}</p>)}</details>:"—"}</td><td>{buy?`${buy.final_quantity??buy.suggested_quantity} 份 · NT$ ${(Number(buy.unit_price)*Number(buy.final_quantity??buy.suggested_quantity)).toLocaleString()}${buy.purchased?" · 已買":""}`:"未列入"}</td></tr>})}</tbody></table></div></div>}</article>})}</div>:<div className="admin-empty">尚無活動紀錄。</div>}</section>}
